package com.quizclash.game.model;

import java.util.List;

/**
 * A quiz question. The same shape is used for the seed file
 * (questions.json) and for questions generated by the AI bot.
 */
public record Question(String id, String question, List<String> options, int correctIndex) {

    public Question {
        if (options == null || options.size() != 4) {
            throw new IllegalArgumentException("A question needs exactly 4 options");
        }
        if (correctIndex < 0 || correctIndex > 3) {
            throw new IllegalArgumentException("correctIndex must be 0..3");
        }
        options = List.copyOf(options);
    }
}
